 1→import { parseLine, parseCounts } from "./parse.js";
 2→import { combine } from "./combine.js";
 3→
 4→/** Total each code's counts across all lines. */
 5→export function tally(lines) {
 6→  const totals = {};
 7→  for (const line of lines) {
 8→    const { code, fields } = parseLine(line);
 9→    totals[code] = (totals[code] ?? 0) + combine(parseCounts(fields));
10→  }
11→  return totals;
12→}

